//! The tax year: what came in, what self-employment tax it carries, and what to put aside.
//!
//! # What this computes, and what it refuses to
//!
//! Self-employment tax is COMPUTABLE. It is a published rate on a published base with a published
//! cap, it needs nothing about the rest of your life, and getting it right is arithmetic.
//!
//! Federal income tax is NOT, and this does not pretend otherwise. It needs filing status, every
//! other source of income, itemised or standard deductions, credits, and a household — none of which
//! a bank statement knows. A number produced without them would be confidently wrong in whichever
//! direction the missing facts pointed, and would be believed because it came out of a machine. So
//! this reports the SE tax it can stand behind, and names income tax as the part somebody else does.
//!
//! # An unseeded year is refused
//!
//! The Social Security wage base changes every year. Applying last year's to this one is the same
//! failure the rate tables were built to prevent, so a year with no parameters answers nothing.
use crate::jurisdiction::apply_bps;
use crate::money::{money, Money};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FilingStatus {
    Single,
    MarriedJointly,
    MarriedSeparately,
    HeadOfHousehold,
}

impl FilingStatus {
    pub fn key(self) -> &'static str {
        match self {
            FilingStatus::Single => "single",
            FilingStatus::MarriedJointly => "joint",
            FilingStatus::MarriedSeparately => "separate",
            FilingStatus::HeadOfHousehold => "head",
        }
    }

    /// Unknown is `None`, never a default — filing status moves the Additional Medicare threshold by
    /// $125,000 between the extremes, and defaulting it would decide somebody's return on a typo.
    pub fn parse(s: &str) -> Option<FilingStatus> {
        match s {
            "single" => Some(FilingStatus::Single),
            "joint" => Some(FilingStatus::MarriedJointly),
            "separate" => Some(FilingStatus::MarriedSeparately),
            "head" => Some(FilingStatus::HeadOfHousehold),
            _ => None,
        }
    }

    pub const ALL: &'static [FilingStatus] =
        &[FilingStatus::Single, FilingStatus::MarriedJointly, FilingStatus::MarriedSeparately, FilingStatus::HeadOfHousehold];

    /// Where the extra 0.9% Medicare surcharge starts. NOT indexed for inflation — these have been
    /// the same figures since 2013, which is why they are constants here rather than per-year data.
    pub fn additional_medicare_threshold_minor(self) -> i64 {
        match self {
            FilingStatus::MarriedJointly => 25_000_000,
            FilingStatus::MarriedSeparately => 12_500_000,
            FilingStatus::Single | FilingStatus::HeadOfHousehold => 20_000_000,
        }
    }
}

/// The parameters of one tax year. DATA, for the same reason every rate in `jurisdiction` is.
#[derive(Debug, Clone, PartialEq)]
pub struct YearParams {
    pub year: i32,
    /// The Social Security wage base — the ceiling on the 12.4% half. Changes EVERY year.
    pub ss_wage_base_minor: i64,
    pub source: &'static str,
    pub note: &'static str,
}

/// 12.4% Social Security. Unchanged since 1990.
pub const SS_BPS: i64 = 1240;
/// 2.9% Medicare, with no ceiling.
pub const MEDICARE_BPS: i64 = 290;
/// An extra 0.9% above a threshold that depends on filing status.
pub const ADDITIONAL_MEDICARE_BPS: i64 = 90;
/// Net earnings are 92.35% of net profit — the deduction standing in for the employer's half.
pub const NET_EARNINGS_BPS: i64 = 9235;
/// Below $400 of net earnings there is no self-employment tax at all.
pub const SE_FLOOR_MINOR: i64 = 40_000;

pub const YEARS: &[YearParams] = &[
    YearParams {
        year: 2024,
        ss_wage_base_minor: 16_860_000,
        source: "SSA — contribution and benefit base, 2024",
        note: "",
    },
    YearParams {
        year: 2025,
        ss_wage_base_minor: 17_610_000,
        source: "SSA — contribution and benefit base, 2025",
        note: "",
    },
    YearParams {
        year: 2026,
        ss_wage_base_minor: 18_450_000,
        source: "SSA — contribution and benefit base, 2026",
        note: "CHECK THIS ONE FIRST. It is the figure this report is most likely to be wrong about, and it only matters if your profit reaches it — the report says whether it actually bound.",
    },
];

pub fn params_for(years: &[YearParams], year: i32) -> Result<YearParams, String> {
    years.iter().find(|y| y.year == year).cloned().ok_or_else(|| {
        let known: Vec<String> = years.iter().map(|y| y.year.to_string()).collect();
        format!(
            "no parameters are recorded for {year}. The Social Security wage base changes every year, so applying another year's would be a wrong number nothing would flag. Known: {}. The figure comes from SSA's contribution and benefit base announcement.",
            known.join(", ")
        )
    })
}

#[derive(Debug, Clone, PartialEq)]
pub struct SelfEmploymentTax {
    pub net_profit: Money,
    /// 92.35% of profit. The base everything below is computed on, and NOT the profit itself.
    pub net_earnings: Money,
    pub social_security: Money,
    pub medicare: Money,
    pub additional_medicare: Money,
    pub total: Money,
    /// Half the regular SE tax, deductible against INCOME tax — it does not reduce the SE tax itself,
    /// and reporting it inside the total would understate what is owed.
    pub deductible_half: Money,
    /// Whether the wage base actually bound. When it did not, the year's most uncertain figure had
    /// no effect on this answer, and saying so is worth more than the caveat it replaces.
    pub cap_bound: bool,
    pub notes: Vec<String>,
}

/// Self-employment tax on a year's net profit.
pub fn self_employment_tax(net_profit: Money, p: &YearParams, status: FilingStatus) -> SelfEmploymentTax {
    let cur = net_profit.currency;
    let zero = money(0, cur);
    let mut notes: Vec<String> = Vec::new();

    // A loss carries no self-employment tax. It may carry other consequences; none of them are here.
    if net_profit.minor <= 0 {
        notes.push("no profit, so no self-employment tax. A LOSS may still matter on a return — that is a question for whoever files it.".to_string());
        return SelfEmploymentTax {
            net_profit,
            net_earnings: zero,
            social_security: zero,
            medicare: zero,
            additional_medicare: zero,
            total: zero,
            deductible_half: zero,
            cap_bound: false,
            notes,
        };
    }

    let net_earnings = apply_bps(net_profit, NET_EARNINGS_BPS);
    if net_earnings.minor < SE_FLOOR_MINOR {
        notes.push(format!(
            "net earnings of {} are below the $400 floor, so no self-employment tax is due. Income tax may still be — the two are separate questions.",
            crate::money::format_minor(net_earnings.minor)
        ));
        return SelfEmploymentTax {
            net_profit,
            net_earnings,
            social_security: zero,
            medicare: zero,
            additional_medicare: zero,
            total: zero,
            deductible_half: zero,
            cap_bound: false,
            notes,
        };
    }

    // The 12.4% half STOPS at the wage base. The 2.9% half never does — that asymmetry is the
    // single most misremembered thing about this tax.
    let cap_bound = net_earnings.minor > p.ss_wage_base_minor;
    let ss_base = money(net_earnings.minor.min(p.ss_wage_base_minor), cur);
    let social_security = apply_bps(ss_base, SS_BPS);
    let medicare = apply_bps(net_earnings, MEDICARE_BPS);

    let threshold = status.additional_medicare_threshold_minor();
    let over = (net_earnings.minor - threshold).max(0);
    let additional_medicare = apply_bps(money(over, cur), ADDITIONAL_MEDICARE_BPS);

    if cap_bound {
        notes.push(format!(
            "the Social Security half stopped at the {} wage base of {}; the Medicare half has no ceiling and was charged on everything",
            p.year,
            crate::money::format_minor(p.ss_wage_base_minor)
        ));
    } else {
        notes.push(format!(
            "profit did not reach the {} wage base, so that figure had no effect on this and does not need checking",
            p.year
        ));
    }
    if over > 0 {
        notes.push(format!(
            "the extra 0.9% Medicare surcharge applies above {} for a {} filer, and it is charged on WAGES PLUS self-employment income — if you also had a job this year, this figure is too low",
            crate::money::format_minor(threshold),
            status.key()
        ));
    }

    let regular = social_security.minor + medicare.minor;
    SelfEmploymentTax {
        net_profit,
        net_earnings,
        social_security,
        medicare,
        additional_medicare,
        // The surcharge is INSIDE the total and OUTSIDE the deduction. Both halves of that are easy
        // to get wrong in opposite directions.
        total: money(regular + additional_medicare.minor, cur),
        deductible_half: money(regular / 2, cur),
        cap_bound,
        notes,
    }
}

/// Where an expense figure came from, because the number is worth very different amounts depending.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ExpenseBasis {
    /// Somebody stated it. The only basis this module trusts.
    Declared,
    /// NOBODY stated it, so it is zero — which makes every figure below the worst case.
    Absent,
}

#[derive(Debug, Clone, PartialEq)]
pub struct TaxYear {
    pub year: i32,
    pub status: FilingStatus,
    pub revenue: Money,
    pub expenses: Money,
    pub expense_basis: ExpenseBasis,
    pub net_profit: Money,
    pub se: SelfEmploymentTax,
    /// What to hold back, at a rate the CALLER chose. Not a prediction of your bill.
    pub set_aside: Option<Money>,
    pub notes: Vec<String>,
}

/// Assemble the year.
///
/// `income_tax_bps` is REQUIRED to be a deliberate choice and is never defaulted: it is the caller's
/// estimate of an income tax rate this module refuses to compute, and a number invented here would be
/// indistinguishable, to a reader, from one that had been derived.
pub fn assemble(
    year: i32,
    status: FilingStatus,
    revenue: Money,
    expenses: Option<Money>,
    income_tax_bps: Option<i64>,
    p: &YearParams,
) -> TaxYear {
    let cur = revenue.currency;
    let (expenses, expense_basis) = match expenses {
        Some(e) => (e, ExpenseBasis::Declared),
        None => (money(0, cur), ExpenseBasis::Absent),
    };
    let net_profit = money(revenue.minor - expenses.minor, cur);
    let se = self_employment_tax(net_profit, p, status);
    let mut notes: Vec<String> = Vec::new();

    if expense_basis == ExpenseBasis::Absent {
        notes.push(
            "NO EXPENSE WAS DECLARED, so this treats every dollar of revenue as profit. That is the worst case and almost certainly too high — a business with no costs is not a business. Pass the deductible total you or your accountant stand behind."
                .to_string(),
        );
    }
    notes.push(
        "INCOME TAX IS NOT COMPUTED HERE and no arithmetic below stands in for it. It needs filing status, every other source of income, deductions, credits and a household — none of which a bank statement knows, and a number produced without them would be believed because a machine printed it."
            .to_string(),
    );
    notes.push(format!(
        "half the regular self-employment tax — {} — is deductible against INCOME tax. It does not reduce the self-employment tax itself, so the {} above is the figure to plan against.",
        crate::money::format_minor(se.deductible_half.minor),
        crate::money::format_minor(se.total.minor)
    ));

    let set_aside = income_tax_bps.map(|bps| {
        // A LOSS SETS ASIDE NOTHING. Applying a rate to a negative profit returned a NEGATIVE
        // set-aside — found by running a year with no revenue and declared expenses, which printed
        // "SET ASIDE -924.00". Money you have not made is not money to hold back, and a negative
        // there reads as an instruction to spend.
        let income = apply_bps(money(net_profit.minor.max(0), cur), bps.max(0));
        money(se.total.minor + income.minor, cur)
    });
    if set_aside.is_none() {
        notes.push(
            "no set-aside is shown because no income tax rate was given. Guessing one would produce the single most actionable number in this report out of nothing."
                .to_string(),
        );
    }

    TaxYear { year, status, revenue, expenses, expense_basis, net_profit, se, set_aside, notes }
}

/// The safe harbour rule for estimated payments, and what of it can actually be computed here.
///
/// The rule that avoids an underpayment penalty is 90% of THIS year's tax or 100% of LAST year's
/// (110% above an AGI threshold). The second path needs last year's return, which this does not have
/// — so it computes the first and names the second rather than silently offering one of two.
pub fn safe_harbour(se: &SelfEmploymentTax) -> (Money, &'static str) {
    (
        apply_bps(se.total, 9000),
        "90% of THIS year's self-employment tax. The other path — 100% of last year's TOTAL tax, or 110% above an AGI threshold — is often lower and is usually the one people use, but it needs last year's return, which this does not have. Both are safe harbours against a penalty, not the bill.",
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    fn p2025() -> YearParams {
        params_for(YEARS, 2025).expect("seeded")
    }

    #[test]
    fn an_unseeded_year_is_refused_rather_than_borrowing_another_years_base() {
        let err = params_for(YEARS, 2019).unwrap_err();
        assert!(err.contains("no parameters are recorded for 2019"), "{err}");
        assert!(err.contains("changes every year"), "the refusal must say WHY: {err}");
        assert!(err.contains("2024, 2025, 2026"), "and what IS known: {err}");
    }

    #[test]
    fn the_ordinary_case_is_arithmetic_anyone_can_check() {
        // $60,000 profit, well under the wage base.
        let se = self_employment_tax(usd(6_000_000), &p2025(), FilingStatus::Single);
        // 60,000 × 0.9235 = 55,410.00
        assert_eq!(se.net_earnings.minor, 5_541_000);
        // 55,410 × 12.4% = 6,870.84
        assert_eq!(se.social_security.minor, 687_084);
        // 55,410 × 2.9% = 1,606.89
        assert_eq!(se.medicare.minor, 160_689);
        assert_eq!(se.additional_medicare.minor, 0);
        assert_eq!(se.total.minor, 847_773, "6,870.84 + 1,606.89 = 8,477.73");
        // Half the regular tax, and it is NOT subtracted from the total.
        assert_eq!(se.deductible_half.minor, 423_886, "half of 8,477.73, rounded down to the cent");
        assert_eq!(se.total.minor, se.social_security.minor + se.medicare.minor + se.additional_medicare.minor);
        assert!(!se.cap_bound);
        assert!(se.notes.iter().any(|n| n.contains("did not reach the 2025 wage base")));
    }

    #[test]
    fn the_wage_base_caps_social_security_and_never_caps_medicare() {
        // THE MOST MISREMEMBERED THING ABOUT THIS TAX. $250,000 profit is over the base.
        let p = p2025();
        let se = self_employment_tax(usd(25_000_000), &p, FilingStatus::Single);
        assert_eq!(se.net_earnings.minor, 23_087_500, "250,000 × 0.9235");
        assert!(se.cap_bound);
        // Social Security stops at the base: 176,100 × 12.4% = 21,836.40
        assert_eq!(se.social_security.minor, 2_183_640);
        assert_eq!(se.social_security.minor, apply_bps(usd(p.ss_wage_base_minor), SS_BPS).minor);
        // Medicare is charged on ALL of it: 230,875 × 2.9% = 6,695.375 → 6,695.38
        assert_eq!(se.medicare.minor, 669_538);
        assert!(se.medicare.minor > apply_bps(usd(p.ss_wage_base_minor), MEDICARE_BPS).minor, "Medicare must not be capped");
        assert!(se.notes.iter().any(|n| n.contains("has no ceiling")));
    }

    #[test]
    fn below_four_hundred_dollars_of_net_earnings_there_is_no_tax_at_all() {
        // $400 of NET EARNINGS, not of profit — so the floor bites at a profit around $433.
        let just_under = self_employment_tax(usd(43_000), &p2025(), FilingStatus::Single);
        assert_eq!(just_under.net_earnings.minor, 39_711, "430 × 0.9235 = 397.11, under the floor");
        assert_eq!(just_under.total.minor, 0);
        assert!(just_under.notes.iter().any(|n| n.contains("below the $400 floor")));
        assert!(just_under.notes.iter().any(|n| n.contains("Income tax may still be")), "the floor is not a general exemption");

        let just_over = self_employment_tax(usd(44_000), &p2025(), FilingStatus::Single);
        assert_eq!(just_over.net_earnings.minor, 40_634, "440 × 0.9235 = 406.34, over the floor");
        assert!(just_over.total.minor > 0);
    }

    #[test]
    fn a_loss_carries_no_self_employment_tax_and_says_it_may_still_matter() {
        let se = self_employment_tax(usd(-500_000), &p2025(), FilingStatus::Single);
        assert_eq!(se.total.minor, 0);
        assert_eq!(se.net_earnings.minor, 0);
        assert!(se.notes.iter().any(|n| n.contains("A LOSS may still matter")));
        // Exactly zero is not a loss and not taxable either, and must not panic.
        assert_eq!(self_employment_tax(usd(0), &p2025(), FilingStatus::Single).total.minor, 0);
    }

    #[test]
    fn the_surcharge_threshold_moves_with_filing_status() {
        // $230,000 profit → 212,405 net earnings. Over the $200k single threshold, under the $250k
        // joint one. Same profit, different tax, and nothing but the status changed.
        let profit = usd(23_000_000);
        let single = self_employment_tax(profit, &p2025(), FilingStatus::Single);
        let joint = self_employment_tax(profit, &p2025(), FilingStatus::MarriedJointly);
        assert_eq!(single.net_earnings.minor, 21_240_500);
        // (212,405 − 200,000) × 0.9% = 111.645 → 111.65
        assert_eq!(single.additional_medicare.minor, 11_165);
        assert_eq!(joint.additional_medicare.minor, 0, "under the joint threshold");
        assert!(single.total.minor > joint.total.minor);
        // Separate filers have the LOWEST threshold, which surprises people.
        let separate = self_employment_tax(profit, &p2025(), FilingStatus::MarriedSeparately);
        assert!(separate.additional_medicare.minor > single.additional_medicare.minor);
        assert!(single.notes.iter().any(|n| n.contains("if you also had a job this year, this figure is too low")));
    }

    #[test]
    fn the_surcharge_is_inside_the_total_and_outside_the_deduction() {
        // Two errors in opposite directions, both easy: leaving it out of the total understates the
        // bill, and including it in the deduction overstates the relief.
        let se = self_employment_tax(usd(30_000_000), &p2025(), FilingStatus::Single);
        assert!(se.additional_medicare.minor > 0);
        assert_eq!(se.total.minor, se.social_security.minor + se.medicare.minor + se.additional_medicare.minor);
        assert_eq!(se.deductible_half.minor, (se.social_security.minor + se.medicare.minor) / 2);
        assert!(se.deductible_half.minor * 2 < se.total.minor, "the surcharge is not halved into the deduction");
    }

    #[test]
    fn every_filing_status_key_round_trips_and_a_near_miss_does_not() {
        for s in FilingStatus::ALL {
            assert_eq!(FilingStatus::parse(s.key()), Some(*s));
        }
        assert_eq!(FilingStatus::ALL.len(), 4);
        assert_eq!(FilingStatus::parse("married"), None, "a near miss must not resolve — it moves the threshold by $125,000");
        // Head of household shares the single threshold; joint and separate do not.
        assert_eq!(
            FilingStatus::HeadOfHousehold.additional_medicare_threshold_minor(),
            FilingStatus::Single.additional_medicare_threshold_minor()
        );
        assert_eq!(FilingStatus::MarriedSeparately.additional_medicare_threshold_minor(), 12_500_000);
    }

    #[test]
    fn an_absent_expense_figure_is_flagged_as_the_worst_case_rather_than_taken_as_zero() {
        let y = assemble(2025, FilingStatus::Single, usd(6_000_000), None, None, &p2025());
        assert_eq!(y.expense_basis, ExpenseBasis::Absent);
        assert_eq!(y.net_profit.minor, 6_000_000, "every dollar of revenue treated as profit");
        assert!(y.notes.iter().any(|n| n.contains("a business with no costs is not a business")));
        // Declaring expenses changes the basis AND the profit.
        let z = assemble(2025, FilingStatus::Single, usd(6_000_000), Some(usd(1_500_000)), None, &p2025());
        assert_eq!(z.expense_basis, ExpenseBasis::Declared);
        assert_eq!(z.net_profit.minor, 4_500_000);
        assert!(z.se.total.minor < y.se.total.minor);
        assert!(!z.notes.iter().any(|n| n.contains("worst case")));
    }

    #[test]
    fn income_tax_is_never_computed_and_the_report_says_so_every_time() {
        for expenses in [None, Some(usd(1_000_000))] {
            for rate in [None, Some(2200)] {
                let y = assemble(2025, FilingStatus::Single, usd(6_000_000), expenses, rate, &p2025());
                assert!(
                    y.notes.iter().any(|n| n.contains("INCOME TAX IS NOT COMPUTED HERE")),
                    "the disclaimer is not conditional on how the report was asked for"
                );
            }
        }
    }

    #[test]
    fn no_set_aside_is_offered_without_a_rate_somebody_chose() {
        // The most actionable number in the report, so it is the one that must not be invented.
        let none = assemble(2025, FilingStatus::Single, usd(6_000_000), Some(usd(1_000_000)), None, &p2025());
        assert_eq!(none.set_aside, None);
        assert!(none.notes.iter().any(|n| n.contains("out of nothing")));

        // 50,000 profit → SE 7,064.78 (rounded through the same path) plus 22% of 50,000 = 11,000.
        let some = assemble(2025, FilingStatus::Single, usd(6_000_000), Some(usd(1_000_000)), Some(2200), &p2025());
        let expected = some.se.total.minor + apply_bps(usd(5_000_000), 2200).minor;
        assert_eq!(some.set_aside, Some(usd(expected)));
        assert_eq!(apply_bps(usd(5_000_000), 2200).minor, 1_100_000);
    }

    #[test]
    fn a_loss_sets_aside_nothing_rather_than_a_negative_amount() {
        // FOUND BY RUNNING IT: a year with no revenue and 4,200.00 of declared expenses printed
        // "SET ASIDE -924.00" — 22% of a negative profit. Money you have not made is not money to
        // hold back, and a negative figure there reads as an instruction to spend.
        let y = assemble(2025, FilingStatus::MarriedJointly, usd(0), Some(usd(420_000)), Some(2200), &p2025());
        assert_eq!(y.net_profit.minor, -420_000, "the loss itself is still reported");
        assert_eq!(y.se.total.minor, 0);
        assert_eq!(y.set_aside, Some(usd(0)), "nothing to set aside, and NOT a negative amount");

        // Exactly break-even is the same answer and must not go negative either.
        assert_eq!(assemble(2025, FilingStatus::Single, usd(100_000), Some(usd(100_000)), Some(2200), &p2025()).set_aside, Some(usd(0)));
        // And a real profit is unaffected by the clamp.
        let ok = assemble(2025, FilingStatus::Single, usd(6_000_000), Some(usd(1_000_000)), Some(2200), &p2025());
        assert_eq!(ok.set_aside, Some(usd(ok.se.total.minor + 1_100_000)));
    }

    #[test]
    fn the_safe_harbour_computes_the_path_it_has_and_names_the_one_it_does_not() {
        let se = self_employment_tax(usd(6_000_000), &p2025(), FilingStatus::Single);
        let (amount, note) = safe_harbour(&se);
        assert_eq!(amount.minor, apply_bps(se.total, 9000).minor);
        assert_eq!(amount.minor, 762_996, "90% of 8,477.73");
        assert!(note.contains("needs last year's return"), "{note}");
        assert!(note.contains("not the bill"), "a safe harbour is a penalty shield, not an estimate: {note}");
    }

    #[test]
    fn every_seeded_year_cites_a_source_and_the_bases_only_rise() {
        assert!(YEARS.len() >= 3, "the scan found only {} years", YEARS.len());
        for y in YEARS {
            assert!(!y.source.trim().is_empty(), "{} has no source", y.year);
            assert!(y.ss_wage_base_minor > 0);
        }
        // The wage base is indexed to average wages and has never fallen. A seeded value that dropped
        // would be a typo, and this is the cheapest place to catch one.
        for w in YEARS.windows(2) {
            assert!(w[1].year > w[0].year, "years must be in order");
            assert!(w[1].ss_wage_base_minor > w[0].ss_wage_base_minor, "{} is not above {}", w[1].year, w[0].year);
        }
        // The most uncertain figure says so on itself, not only in prose somewhere else.
        assert!(params_for(YEARS, 2026).expect("seeded").note.contains("CHECK THIS ONE FIRST"));
    }

    #[test]
    fn the_rates_are_the_published_ones() {
        // Stated as constants so a typo is visible here rather than inside a total.
        assert_eq!(SS_BPS + MEDICARE_BPS, 1530, "15.3% combined");
        assert_eq!(NET_EARNINGS_BPS, 9235);
        assert_eq!(SE_FLOOR_MINOR, 40_000, "$400");
        assert_eq!(ADDITIONAL_MEDICARE_BPS, 90);
    }
